import { useRef } from 'react';
import { useDrag, useDrop } from 'react-dnd';
import DragIndicatorIcon from '@mui/icons-material/DragIndicator';
import Iconify from 'src/components/iconify/Iconify';

const style = {
  display: 'flex',
  columnGap: '8px',
  justifyContent: 'space-between',
  padding: '6px 12px',
  border: '1px solid #ccc',
  borderRadius: '8px',
  textTransform: 'capitalize',
};
const DragPage = ({ name, title, index, moveCard, source, stepIndex, editable=true, edit, handleDelete, active }) => {
  const ref = useRef(null)
  const dropRef = useRef(null)
  const data = { name, index, source, stepIndex };
  const [{ handlerId, isOver }, drop] = useDrop({
    accept: 'pages',
    type: 'pages',
    item: data,
    collect(monitor) {
      return {
        handlerId: monitor.getHandlerId(),
        isOver: !!monitor.isOver(),
      }
    },
    hover(item, monitor) {
      if (!ref.current) {
        return
      }
      console.log('item', item)
      const dragIndex = item.index
      const hoverIndex = index
      // console.log('hoverIndex', hoverIndex, dragIndex)
      // Don't replace items with themselves
      if (dragIndex === hoverIndex) {
        console.log('equal')
        return
      }
      // Determine rectangle on screen
      const hoverBoundingRect = ref.current?.getBoundingClientRect()
      // Get vertical middle
      const hoverMiddleY =
        (hoverBoundingRect.bottom - hoverBoundingRect.top) / 2
      // Determine mouse position
      const clientOffset = monitor.getClientOffset()
      // Get pixels to the top
      const hoverClientY = clientOffset.y - hoverBoundingRect.top
      // Only perform the move when the mouse has crossed half of the items height
      // When dragging downwards, only move when the cursor is below 50%
      // When dragging upwards, only move when the cursor is above 50%
      // Dragging downwards
      if (dragIndex < hoverIndex && hoverClientY < hoverMiddleY) {
        console.log('less')
        return
      }
      // Dragging upwards
      if (dragIndex > hoverIndex && hoverClientY > hoverMiddleY) {
        console.log('more')
        return
      }
      console.log('dropssMoveCard', index, name);
      // Time to actually perform the action
      moveCard(item, hoverIndex, index, stepIndex)
      // Note: we're mutating the monitor item here!
      // Generally it's better to avoid mutations,
      // but it's good here for the sake of performance
      // to avoid expensive index searches.
      item.index = hoverIndex
    },
  })

  const [{ opacity }, drag, preview] = useDrag(
    () => ({
      type: 'pages',
      item: () => {
        return data
      },
      collect: (monitor) => ({
        opacity: monitor.isDragging() ? 0.4 : 1,
        handlerId: monitor.getHandlerId(),
      }),
    }),
    [name]
  );
  
    const onDelete = () => {
      handleDelete(index);
    }

    drag(ref)
    drop(preview(dropRef));
    return (
      <div ref={dropRef} style={{ ...style, opacity, backgroundColor: isOver? '#ccc': active? 'rgba(145, 158, 171, 0.12)': '#fff' }} data-handler-id={handlerId}>
        {title || name?.replace(/\//g, '')}
        {edit && <div className='d-flex'>
        {editable && <Iconify icon={'eva:trash-2-outline'} sx={{ mr: 2, cursor: 'pointer' }} onClick={onDelete} />}
          <div ref={ref} style={{cursor:'move'}}>
        <DragIndicatorIcon />
          </div>
        </div>}
      </div>
    )
  
};
export default DragPage;