import React, { useEffect, useState, useCallback, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { Helmet } from 'react-helmet-async';
import { Card, Grid, Button, Typography, IconButton, InputAdornment, Divider, Box } from '@mui/material';
import InputLabel from '@mui/material/InputLabel';
import GenerateToastConfig from 'src/components/toast-config/GenerateToastConfig';
import { useFieldArray, useForm, Controller } from 'react-hook-form';
import InputGallery from 'src/components/inputGallery';
import { axios } from '../../utils/axios';
import { useMyContext } from '../../pages/provider';
import ImageUpload from '../input/imageUpload';
import InputField from '../input/inputField';
import useResponsive from '../../hooks/useResponsive';
import DragPage from './DragPage';
import DragContainer from './DragContainer';
import PagesChildren from './PagesChildren';
import styles from './formManagement.module.scss';

const fieldArrayName = 'steps';

export default function FormManagementPage({type, edit}) {
  const navigate = useNavigate();
  const [images, setImg] = useState('');
  const { i18 } = useMyContext();
  const isMobile = useResponsive('down', 'sm');
  const [pages, setPages] = useState([]);
  const [rand, setRand] = useState();
  const { control, reset, getValues, setValue, handleSubmit } = useForm();
  const { fields, remove, move, replace, insert } = useFieldArray({
    control, // control props comes from useForm (optional: if you are using FormProvider)
    name: fieldArrayName, // unique name for your Field Array
  });

  const filteredPages = useMemo(() => {
    let myPages = [];
    const fields = getValues(fieldArrayName);
    console.log('fieldssss', fields);
    if (Array.isArray(fields)) {
      for (let i = 0; i < fields.length; i += 1) {
        if (Array.isArray(fields[i].pages)) {
          myPages = [...myPages, ...fields[i].pages];
        }
      }
      const pageList = myPages.map((item) => item.name);
      myPages = myPages.map((item) => {
        item.found = true;
        return item;
      });

      const notFound = pages.filter((item) => !pageList.includes(item.name));
      myPages = [...myPages, ...notFound];
    }
    return myPages;
  }, [pages, rand]);

  console.log('filteredPages', filteredPages);

  const fetchData = async () => {
    const res = await axios.get(`module/${type}/getSteps`);
    if (res.data.statusCode) {
      const data = res?.data?.data;
      if (Array.isArray(data?.steps)) {
        reset({
          [fieldArrayName]: data?.steps,
        });
      }

      if (Array.isArray(data?.pages)) {
        setPages(data?.pages);
      }
    }
  };

  const filterPages = (pageId) => {
    const clonedFields = getValues(fieldArrayName);
    for (let i = 0; i < clonedFields.length; i += 1) {
      clonedFields[i].pages = clonedFields[i].pages.filter((item) => item.name !== pageId);
    }
    return clonedFields;
  };

  const moveCard = (item, hoverIndex, sourceIndex, stepIndex) => {
    if (item.source === 'pages') {
      // filter from source pages list
      if (typeof stepIndex === 'number') {
        const data = pages.find((sub) => sub.name === item.name);
        const clonedFields = filterPages(data.name);
        const clonedPages = clonedFields[stepIndex].pages;
        clonedPages.splice(hoverIndex, 0, data);
        setValue(`${fieldArrayName}`, clonedFields, { shouldValidate: true });
        setRand(Date.now());
        // setValue(`${fieldArrayName}.${stepIndex}.pages`, clonedPages, { shouldValidate: true })
      }
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  const onSelectedImg = (img, data) => {
    if(img[0]) {
      const fields = getValues(fieldArrayName);
      const clonedFields = [...fields];
      clonedFields[data.index][data.type] = img[0].imagePath;
      replace(clonedFields);
    }
  }

  const handleUploadedFile = (event) => {
    const file = event.target.files[0];
    setImg(file);
  };

  const handleDrop = (drop, monitor) => {
    console.log('type', monitor.getItemType());
    console.log(fields, 'fields');
    // console.log('index', index);
  };

  const handleAdd = (index) => {
    insert(index, {
      title: '',
      subTitle: '',
      description: '',
      icon: '',
      image: '',
      pages: [],
    });
  };

  const onSubmit = async (values) => {
    const res = await axios.put(`module/${type}/admin/config`, values);
    GenerateToastConfig(res.data.message, 'success');
  };
  return (
    <>
      <Helmet>
        <title className='text-capitalize'>{type} {i18?.FORM?.FORM_MANAGEMENT || 'Form Management'}</title>
      </Helmet>

      <Typography variant="h4" gutterBottom sx={{ margin: '0px 0px 0px 10px', paddingBottom: '0px' }} className='text-capitalize'>
      {type} {i18?.FORM?.FORM_MANAGEMENT || 'Form Management'}
      </Typography>
      <form onSubmit={handleSubmit(onSubmit)} className="d-flex h-100 overflow-auto gap-2 align-items-start">
        {edit && <Card sx={{ position: 'sticky', minWidth: '300px', top: '0px', overflow: 'auto', height: '100%' }}>
          <Grid container sx={{ padding: '10px 30px', margin: '10px 0px' }}>
            <Grid container item justifyContent="space-between" alignItems="center" sx={{ marginRight: '10px' }}>
              <Box sx={{ display: 'flex', alignItems: 'center' }}>
                <Typography variant="h6" gutterBottom sx={{ margin: '0px 0px 0px 0px', paddingBottom: '0px' }}>
                  {i18?.FORM?.PAGES || 'Pages'}
                </Typography>
              </Box>
            </Grid>
          </Grid>
          <Divider sx={{ backgroundColor: '#333', margin: '10px 0px 10px 0px' }} />
          <DragContainer handleDrop={handleDrop}>
            {filteredPages.map((item, index) => (
              <DragPage
                moveCard={moveCard}
                source="pages"
                index={index}
                key={index}
                title={item?.title}
                name={item?.name}
                editable={false}
                active={item.found}
                edit={edit}
              />
            ))}
          </DragContainer>
        </Card>}
        <div className="d-flex flex-column gap-3">
          {fields.map((field, index) => {
            return (
              <Card key={field.id}>
                <Grid container sx={{ padding: '10px 30px', margin: '10px 0px' }}>
                  <Grid container item justifyContent="space-between" alignItems="center" sx={{ marginRight: '10px' }}>
                    <Box sx={{ display: 'flex', alignItems: 'center' }}>
                      <Typography variant="h6" gutterBottom sx={{ margin: '0px 0px 0px 10px', paddingBottom: '0px' }}>
                        {i18?.FORM?.STEP || 'Step'} {index + 1}
                      </Typography>
                    </Box>

                    {edit && <Box sx={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                      <Button
                        sx={{
                          padding: '10px 58px 10px 58px',
                        }}
                        onClick={() => handleAdd(index)}
                        variant="contained"
                        disabled={false}
                      >
                        {i18?.FORM?.ADD || 'Add'}
                      </Button>
                      <Button
                        sx={{
                          padding: '10px 58px 10px 58px',
                          background: '#FF5A60',
                          '&:hover': {
                            background: '#FF4A50',
                          },
                        }}
                        onClick={() => {
                          setRand(Date.now());
                          remove(index)
                        }}
                        variant="contained"
                        disabled={false}
                      >
                        {i18?.FORM?.REMOVE || 'Remove'}
                      </Button>
                    </Box>}
                  </Grid>
                </Grid>
                <Divider sx={{ backgroundColor: '#333', margin: '10px 0px 10px 0px' }} />
                <Grid container={!isMobile} sx={{ padding: '10px 30px', margin: '10px 0px' }}>
                  <Grid container={!isMobile} sx={{ marginTop: '10px' }}>
                    <Grid item xs={12} sx={{ padding: !isMobile ? '10px 50px 10px 0px' : '0px 5px' }}>
                      <Controller
                        control={control}
                        name={`${fieldArrayName}.${index}.title`}
                        render={({ field }) => (
                          <InputField
                            label={i18?.FORM?.TITLE || 'Title'}
                            {...field}
                            sx={{
                              margin: '10px 0px',
                              width: '100%',
                              '& .MuiInputBase-input.MuiOutlinedInput-input': {
                                padding: '10.5px 14px',
                              },
                            }}
                            type="firstname"
                            // error={firstname}
                            // helperText={firstname}
                          />
                        )}
                      />
                    </Grid>
                  </Grid>
                  <Grid item xs={6} sx={{ padding: !isMobile ? '10px 50px  10px 0px' : '0px 5px' }}>
                    <InputLabel sx={{ color: '#2B3343' }} id="demo-simple-select-label">
                      {i18?.FORM?.SUB_TITLE || 'Sub Title'}
                    </InputLabel>
                    <Controller
                      control={control}
                      name={`${fieldArrayName}.${index}.subTitle`}
                      render={({ field }) => (
                        <textarea
                          rows={5}
                          {...field}
                          className="textArea"
                          placeholder="Enter text here..."
                          style={{
                            width: '100%',
                            marginBottom: '20px',
                            padding: '8px',
                            borderRadius: '4px',
                            borderColor: '#ccc',
                            resize: 'none',
                          }}
                        />
                      )}
                    />
                  </Grid>

                  <Grid item xs={6} sx={{ padding: !isMobile ? '10px 50px  10px 0px' : '0px 5px' }}>
                    <InputLabel sx={{ color: '#2B3343' }} id="demo-simple-select-label">
                      {i18?.FORM?.DESCRIPTION || 'Description'}
                    </InputLabel>
                    <Controller
                      control={control}
                      name={`${fieldArrayName}.${index}.description`}
                      render={({ field }) => (
                        <textarea
                          rows={5}
                          {...field}
                          className="textArea"
                          placeholder="Enter text here..."
                          style={{
                            width: '100%',
                            marginBottom: '20px',
                            padding: '8px',
                            borderRadius: '4px',
                            borderColor: '#ccc',
                            resize: 'none',
                          }}
                        />
                      )}
                    />
                  </Grid>
                  <div className="d-flex gap-2 w-100 mb-3">
                    <div className="d-flex flex-column gap-1">
                    <InputGallery
              category='icons'
              fnc={onSelectedImg}
              fncData={{index, type: 'icon'}}
              selectedImages={field.icon?[field.icon]:[]}
              imageCount={1}
              />
                      {/* <InputLabel sx={{ color: '#2B3343' }} id="demo-simple-select-label">
                        {i18?.FORM?.ICON || 'Icon'}
                      </InputLabel>
                      <ImageUpload value={images} onChange={handleUploadedFile} /> */}
                    </div>

                    <div className="d-flex flex-column gap-1">
                    <InputGallery
              category='listings'
              fnc={onSelectedImg}
              fncData={{index, type: 'image'}}
              selectedImages={field.image?[field.image]:[]}
              imageCount={1}
              />
                      {/* <InputLabel sx={{ color: '#2B3343' }} id="demo-simple-select-label">
                        {i18?.FORM?.IMAGE || 'Image'}
                      </InputLabel>
                      <ImageUpload value={images} onChange={handleUploadedFile} /> */}
                    </div>
                  </div>
                  <div className="w-100 mb-2">
                    <InputLabel sx={{ color: '#2B3343' }} id="demo-simple-select-label">
                      {i18?.FORM?.PAGES || 'Pages'}
                    </InputLabel>
                  </div>
                  <PagesChildren
                    setRand={setRand}
                    pages={filteredPages}
                    moveCard={moveCard}
                    fieldArrayName={fieldArrayName}
                    stepIndex={index}
                    control={control}
                    edit={edit}
                  />
                  {/* <DragContainer>
                      {field.pages.map((item, index)=>(<DragPage index={index} moveCard={moveCard} key={index} name={item.title || item.name.replace(/\//g, '')} />))}
                    </DragContainer> */}
                </Grid>
              </Card>
            );
          })}
          <Grid container justifyContent="flex-end" gap={2} sx={{ padding: '10px 30px', margin: '10px 0px' }}>
            <Button
              sx={{
                padding: '10px 58px 10px 58px',
                background: '#FF5A60',
                '&:hover': {
                  background: '#FF4A50',
                },
              }}
              onClick={() => {
                setRand(Date.now());
                reset()
              }}
              variant="contained"
              disabled={false}
            >
              {i18?.FORM?.Reset || 'Reset'}
            </Button>
          {edit &&
            <Button
              sx={{
                padding: '10px 58px 10px 58px',
              }}
              onClick={() => handleAdd(fields.length)}
              variant="contained"
              disabled={false}
            >
              {i18?.FORM?.ADD || 'Add'}
            </Button>}

            <Button
              sx={{
                padding: '10px 58px 10px 58px',
              }}
              type="submit"
              variant="contained"
              disabled={false}
            >
              {i18?.FORM?.SAVE || 'Save'}
            </Button>
          </Grid>
        </div>
      </form>
    </>
  );
}
