/* eslint no-else-return: "error" */
import { useDrop } from 'react-dnd';

function selectBackgroundColor(isActive, canDrop, type) {
  if(type==='steps') {
  if (isActive) {
    return '#e5e7eb';
  } else if (canDrop) {
    return '#f1f5f9';
  }
}
  return '#fff';
}

const DragContainer = ({ allowedDropEffect, children, handleDrop, type }) => {
  const style = {
    minHeight: '50px',
    minWidth: type==='steps'? '360px':'auto'
  };
  const [{ canDrop, isOver }, drop] = useDrop(
    () => ({
      accept: 'pages',
      type: 'pages',
      drop: handleDrop,
      collect: (monitor) => ({
        isOver: monitor.isOver(),
        canDrop: monitor.canDrop(),
      }),
    }),
    [allowedDropEffect]
  );
  const isActive = canDrop && isOver;
  const backgroundColor = selectBackgroundColor(isActive, canDrop, type);
  return (
    <div ref={drop} className="d-flex gap-2 flex-column px-2 mb-4 py-4" style={{ ...style, backgroundColor }}>
      {children}
    </div>
  );
};
export default DragContainer;
