import React, { useCallback, useState } from 'react'
import { useFieldArray } from 'react-hook-form';
import DragPage from './DragPage';
import DragContainer from './DragContainer';
import DeleteModal from '../deleteModal/DeleteModal';

function PagesChildren({fieldArrayName, control, stepIndex, moveCard, pages, setRand, edit}) {
  const [opens, setOpens] = useState(false);
  const [data, setData] = useState();
  const { fields, swap, remove } = useFieldArray({
    control, // control props comes from useForm (optional: if you are using FormProvider)
    name: `${fieldArrayName}.${stepIndex}.pages`, // unique name for your Field Array
  });

  const LocalmoveCard = (item, hoverIndex, sourceIndex, stepIndex) => {
    if (item.source === 'steps' && item.stepIndex === stepIndex) {
      swap(item.index, hoverIndex)
      setRand(Date.now());
      return;
    }
    moveCard(item, hoverIndex, sourceIndex, stepIndex);
  }

  // const moveCard = useCallback((dragIndex, hoverIndex, source, sourceIndex, stepIndex) => {

  //   move(dragIndex, hoverIndex)
  // }, [])


  const handleDrop = useCallback((obj) => {
    if (obj.source === 'pages') {
      const item = pages.find((item) => item.name === obj.name);
      item.source = 'pages'
      moveCard(item, obj.index, obj.index, stepIndex);
    }
  }, [])

  const handleDelete = (index) => {
    setData(index)
    setOpens(true);
  }

  const executeDelete = () => {
    remove(data)
    setRand(Date.now());
    setOpens(false);
  }
  return (
    <>
      <DragContainer handleDrop={handleDrop} type='steps'>
        {fields.map((item, index) => (<DragPage edit={edit} index={index} stepIndex={stepIndex} moveCard={LocalmoveCard} key={index} source='steps' title={item?.title} name={item?.name} handleDelete={handleDelete} />))}
      </DragContainer>
      <DeleteModal
        isDeleteOpen={opens}
        handleClose={() => setOpens(false)}
        handleDelete={executeDelete}
      />
    </>)
}

export default PagesChildren
